modules.storm:
// huntbase.hub — map Huntbase Hub hunts onto the Synapse plan:* model.
//
//   hunt            -> plan:procedure        (:body = the hunt.md source)
//   definition node -> plan:procedure:step   (query steps -(uses)> meta:rule)
//   parents[]       -> plan:procedure:link   (checkpoint branches -> :condition)
//   parameters      -> plan:procedure:variable (procedure :inputs)
//   techniques      -> meta:technique        (procedure -(refs)>)
//   cves            -> risk:vuln             (procedure -(refs)>)
//   source report   -> doc:report            (procedure -(refs)>)
//
// Every guid is derived from the hub slug and step id, so re-ingesting a hunt
// updates the same nodes rather than creating copies.
//
// Synapse 2.x has the same plan:* forms with fewer props, and no
// meta:technique or doc:report. On a 2.x Cortex the module writes:
//
//   :desc           -> :summary            (plan:procedure, plan:procedure:step)
//   :id :body :url  -> node data + -(refs)> inet:url   (plan:procedure)
//   meta:rule:id    -> meta:rule:ext:id
//   meta:technique  -> it:mitre:attack:technique
//   risk:vuln:id    -> risk:vuln:cve
//   doc:report      -> media:news

$system = $lib.guid(huntbase, hub, plan, system, hunt.md)

// true on a Synapse 2.x data model
$model2 = ($lib.model.prop("plan:procedure:body") = (null))

function fetch(url, json=(true)) {
    $resp = $lib.inet.http.get($url)
    if ($resp.code != 200) {
        $lib.warn(`huntbase.hub: GET {$url} returned {$resp.code}`)
        return((null))
    }
    if $json { return($resp.json()) }
    return($resp.body.decode())
}

function tagPart(text) {
    if ($text = (null)) { return("unknown") }
    return($lib.regex.replace("[^a-z0-9_]+", "_", $text.lower()))
}

function getSource(url) {
    [ meta:source=({"name": "huntbase hub", "url": $url}) :url=$url :type=intel.feed.hunts ]
    return($node)
}

function setCursor(url, latest) {
    [ meta:source=({"name": "huntbase hub", "url": $url}) :url=$url :ingest:latest=$latest ]
    return()
}

// When the hub last changed a hunt: its `updated` time where the index has
// one, otherwise when it was published. The sync cursor follows this, so an
// edited hunt is pulled again.
function entryTime(entry) {
    if $entry.updated { return($entry.updated) }
    return($entry.generated.at)
}

function stepGuid(slug, stepid) {
    return($lib.guid(huntbase, hub, step, $slug, $stepid))
}

// A hub branch name on a parent edge -> plan:procedure:link :condition.
function branchCondition(branch) {
    if ($branch = "on_supports") { return((true)) }
    if ($branch = "on_refutes") { return((false)) }
    return((null))
}

function ingestHunt(url, entry, defn, text) {

    // Storm streams nodes: anything that loops over the procedure node is
    // wrapped in its own { } subquery, which drains before the node moves on,
    // so each loop runs to completion exactly once.

    $slug = $entry.slug
    $proc = $lib.guid(huntbase, hub, procedure, $slug)
    $page = `{$url}/{$entry.path}`
    $meta = $defn.hunt.meta

    [ plan:procedure=$proc
        :title?=$entry.title
        :type=huntbase.hunt
        :system={[ plan:system=$system :name=hunt.md :url=https://github.com/huntbase-io/hunt-md ]}
        :created?=$entry.generated.at
        :updated?=$entryTime($entry)
        +#rep.huntbase.hunt
        <(seen)+ {[ meta:source=({"name": "huntbase hub", "url": $url}) ]}
    ]
    if $model2 {
        [ :summary?=$entry.hypothesis +(refs)> {[ inet:url=$page ]} ]
        $node.data.set(huntbase:hub:slug, $slug)
        if ($text != (null)) { $node.data.set(huntbase:hub:body, $text) }
    } else {
        [ :id=$slug :desc?=$entry.hypothesis :body?=$text :url=$page :creator:name=huntbase ]
    }

    $node.data.set(huntbase:hub:entry, $entry)
    $node.data.set(huntbase:hub:definition, $defn)

    // classification tags
    {
        $tags = ([])
        if $entry.severity { $tags.append(`rep.huntbase.severity.{$tagPart($entry.severity)}`) }
        if $entry.tlp { $tags.append(`rep.huntbase.tlp.{$tagPart($entry.tlp)}`) }
        if $entry.series { $tags.append(`rep.huntbase.series.{$tagPart($entry.series.slug)}`) }
        for $tactic in $entry.tactics { $tags.append(`rep.huntbase.tactic.{$tagPart($tactic)}`) }
        for $product in $entry.products { $tags.append(`rep.huntbase.product.{$tagPart($product)}`) }
        for $tag in $tags { [ +#$tag ] }
    }

    // what the hunt is about
    {
        for $tid in $entry.techniques {
            if $model2 { [ +(refs)> {[ it:mitre:attack:technique=$tid ]} ] }
            else { [ +(refs)> {[ meta:technique=({"id": $tid}) ]} ] }
        }
    }
    {
        for $cve in $entry.cves {
            if $model2 { [ +(refs)> {[ risk:vuln=({"cve": $cve}) ]} ] }
            else { [ +(refs)> {[ risk:vuln=({"id": $cve}) ]} ] }
        }
    }
    {
        if $entry.source.url {
            if $model2 {
                [ +(refs)> {[ media:news=({"url": $entry.source.url})
                    :title?=$entry.source.title
                    :publisher:name?=$entry.source.vendor
                ]} ]
            } else {
                [ +(refs)> {[ doc:report=({"url": $entry.source.url})
                    :title?=$entry.source.title
                    :publisher:name?=$entry.source.vendor
                    :public=(true)
                ]} ]
            }
        }
    }

    // parameters -> procedure inputs
    {
        for ($name, $param) in $meta.parameters {
            $var = $lib.guid(huntbase, hub, variable, $slug, $name)
            { spin | [ plan:procedure:variable=$var
                :procedure={plan:procedure=$proc}
                :name=$name
                :type?=$param.type
                :default?=$param.default
            ] }
            [ :inputs += {plan:procedure:variable=$var} ]
        }
    }

    // steps, then the links between them
    {
        for $step in $defn.nodes {
            $sg = $stepGuid($slug, $step.id)
            $cfg = $step.config
            $steptag = `rep.huntbase.step.{$tagPart($step.type)}`
            { spin | [ plan:procedure:step=$sg
                :procedure={plan:procedure=$proc}
                :title?=$step.label
                +#$steptag
            ]
                if $model2 { [ :summary?=$cfg.description ] }
                else { [ :desc?=$cfg.description ] }
            }
            if ($step.parents = (null)) { [ :firststep={plan:procedure:step=$sg} ] }

            if ($step.type = "query") {
                $rule = $lib.guid(huntbase, hub, query, $slug, $step.id)
                $ruletags = (["rep.huntbase.query"])
                if $cfg.surface { $ruletags.append(`rep.huntbase.surface.{$tagPart($cfg.surface)}`) }
                { spin | [ meta:rule=$rule
                    :name?=$step.label
                    :desc?=$cfg.description
                    :text?=$cfg.content
                    :type=`huntbase.query.{$tagPart($cfg.dsl)}`
                    :url=`{$page}#{$step.id}`
                    <(uses)+ { plan:procedure:step=$sg }
                ]
                if $model2 { [ :ext:id=`{$slug}/{$step.id}` ] }
                else { [ :id=`{$slug}/{$step.id}` :severity?=$entry.severity ] }
                for $tag in $ruletags { [ +#$tag ] } }
            }
        }
    }
    {
        for $step in $defn.nodes {
            $sg = $stepGuid($slug, $step.id)
            for $parent in $step.parents {
                $branch = $parent.branch
                if ($branch = (null)) { $branch = next }
                $link = $lib.guid(huntbase, hub, link, $slug, $parent.id, $step.id, $branch)
                $cond = $branchCondition($parent.branch)
                { spin | [ plan:procedure:link=$link
                    :procedure={plan:procedure=$proc}
                    :next={plan:procedure:step=$sg}
                    :condition?=$cond
                ] }
                $psg = $stepGuid($slug, $parent.id)
                { spin | plan:procedure:step=$psg [ :links += {plan:procedure:link=$link} ] }
            }
        }
    }

    return($node)
}

// Fetch and ingest one hub entry. Returns the plan:procedure node or (null).
function syncEntry(url, entry) {
    $base = `{$url}/{$entry.path}`
    $defn = $fetch(`{$base}definition.json`)
    if ($defn = (null)) { return((null)) }
    $text = $fetch(`{$base}hunt.md`, json=(false))
    // one malformed hunt must not stop a sync
    try {
        return($ingestHunt($url, $entry, $defn, $text))
    } catch * as err {
        $lib.warn(`huntbase.hub: skipped {$entry.slug}: {$err.mesg}`)
        return((null))
    }
}

commands.desc:
Pull new and changed hunts from the Huntbase Hub into the current view.

Examples:
  // pull everything published or changed since the last sync
  huntbase.hub.sync
  // first ten hunts only, ignoring the cursor
  huntbase.hub.sync --all --size 10

commands.storm:
init {
    $hub = $lib.import(huntbase.hub)
    $url = $cmdopts.url.rstrip("/")

    $index = $hub.fetch(`{$url}/index.json`)
    if ($index = (null)) { $lib.exit("huntbase.hub.sync: could not read the hub index") }

    $source = $hub.getSource($url)
    $cursor = $source.props."ingest:latest"
    if $cmdopts.all { $cursor = (null) }

    // a hunt is due when it changed after the cursor: its `updated` time,
    // or its publication time on a hub that does not list one.
    // oldest first, so a --size limited run advances the cursor without
    // skipping the hunts it did not reach
    $pending = ([])
    for $i in $lib.range($index.size()) {
        $at = $lib.cast(time, $hub.entryTime($index.$i))
        if ($cursor = (null) or $at > $cursor) { $pending.append(($at, $i)) }
    }

    $count = (0)
    $newest = $cursor
    for ($at, $i) in $lib.sorted($pending) {
        if ($cmdopts.size > 0 and $count >= $cmdopts.size) { break }
        $entry = $index.$i
        $proc = $hub.syncEntry($url, $entry)
        if ($proc = (null)) { continue }
        $count = ($count + 1)
        if ($newest = (null) or $at > $newest) { $newest = $at }
    }

    if ($newest != (null)) {
        $hub.setCursor($url, $newest)
    }
    $lib.print(`huntbase.hub.sync: ingested {$count} hunt(s) from {$url}`)
}

init {
    $hub = $lib.import(huntbase.hub)
    $url = $cmdopts.url.rstrip("/")
    $index = $hub.fetch(`{$url}/index.json`)
    $wanted = $lib.set()
    for $slug in $cmdopts.slugs { $wanted.add($slug) }
}
for $entry in $index {
    if $wanted.has($entry.slug) {
        $proc = $hub.syncEntry($url, $entry)
        if ($proc != (null)) { yield $proc }
    }
}
